SELECT UO.*,
UOS.user_agent AS last_user_agent,
UOS.ip AS last_ip,
UOS.login_time AS last_login_time,
UOS.device AS last_device
FROM ucenter_oauth UO
LEFT JOIN LATERAL ( SELECT oauth_id, IT.login_time, IT.device, IT.ip, IT.user_agent
FROM ucenter_oauth_session IT
WHERE IT.oauth_id = UO.id
ORDER BY id DESC
LIMIT 1) UOS ON UOS.oauth_id = UO.id
WHERE UO.deleted = 0

    AND UO.uid = #{q.uid}


    AND UO.provider = #{q.provider}


    AND UO.app_id = #{q.appId}


    AND UO.open_id = #{q.openId}


    AND UO.union_id = #{q.unionId}


    AND UO.ip = #{q.ip}


    AND UO.device = #{q.device}


     AND UO.created_at >= #{q.createStartTime} 


     AND UO.created_at <= #{q.createEndTime} 


     AND UO.login_time >= #{q.loginStartTime} 


     AND UO.login_time <= #{q.loginEndTime} 


    AND UO.spm LIKE #{q.spm}

SELECT *
FROM ucenter_oauth
WHERE app_id = #{app}
  AND provider = #{provider}
  AND open_id = #{openId}
